import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../../utils/api';

function IngredientCustomModal({ visible, item, onClose, onConfirm }) {
  const [excluded, setExcluded] = useState([]);

  useEffect(() => { 
    if (visible) setExcluded([]); 
  }, [visible]);

  if (!visible || !item) return null;

  const toggle = (n) => setExcluded(p => p.includes(n) ? p.filter(x => x !== n) : [...p, n]);
  const optionals = (item.ingredients || []).filter(i => i.optional);

  return (
    <div className="fixed inset-0 bg-black/70 flex items-end sm:items-center justify-center z-50 p-0 sm:p-4 transition-all">
      <div className="bg-gray-800 w-full sm:max-w-md p-6 sm:rounded-2xl rounded-t-3xl border border-gray-700 shadow-2xl animate-slide-up sm:animate-none">
        <h3 className="text-xl font-extrabold text-white text-center">🥗 Customise</h3>
        <p className="text-sm text-gray-400 text-center mt-1 mb-4">{item.name}</p>

        {optionals.length > 0 ? (
          <>
            <p className="text-xs text-gray-400 mb-2">Tap to remove ingredients</p>
            <div className="space-y-2 max-h-60 overflow-y-auto pr-1">
              {optionals.map(ing => {
                const ex = excluded.includes(ing.name);
                return (
                  <button 
                    key={ing.name} 
                    onClick={() => toggle(ing.name)}
                    className={`w-full flex justify-between items-center p-3 rounded-lg border transition ${
                      ex ? 'bg-red-900/20 border-red-500' : 'bg-gray-900 border-transparent hover:border-gray-700'
                    }`}
                  >
                    <span className={`text-sm ${ex ? 'text-red-500 line-through' : 'text-white'}`}>
                      {ex ? '❌ ' : '✅ '}{ing.name}
                    </span>
                    {ex && <span className="text-xs font-bold text-red-500">Removed</span>}
                  </button>
                );
              })}
            </div>
          </>
        ) : (
          <p className="text-gray-400 text-center my-6">No customisable ingredients for this item.</p>
        )}

        <div className="flex gap-3 mt-6">
          <button 
            onClick={onClose} 
            className="flex-1 py-3 rounded-xl border border-gray-600 text-gray-400 font-bold hover:bg-gray-700 transition"
          >
            Cancel
          </button>
          <button 
            onClick={() => onConfirm(excluded)} 
            className="flex-[2] py-3 rounded-xl bg-orange-500 hover:bg-orange-600 text-white font-bold transition shadow-lg"
          >
            Add ₹{item.price}
          </button>
        </div>
      </div>
    </div>
  );
}

export default function HomeChefPage() {
  const navigate = useNavigate();
  const [chefs, setChefs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedChef, setSelectedChef] = useState(null);
  const [cart, setCart] = useState([]);
  const [address, setAddress] = useState('');
  const [ingModal, setIngModal] = useState(false);
  const [ingItem, setIngItem] = useState(null);
  const [placing, setPlacing] = useState(false);
  const [checkoutModal, setCheckoutModal] = useState(false);

  useEffect(() => {
    api.get('/features/home-chefs').then(res => { 
      setChefs(res.data); setLoading(false); 
    }).catch(() => setLoading(false));
  }, []);

  const handleAdd = (item) => { 
    setIngItem(item); setIngModal(true); 
  };

  const handleIngConfirm = (excluded) => {
    setIngModal(false);
    const existing = cart.find(c => c._id === ingItem._id);
    if (existing) {
      setCart(cart.map(c => c._id === ingItem._id ? { ...c, qty: c.qty + 1 } : c));
    } else {
      setCart([...cart, { ...ingItem, qty: 1, excludedIngredients: excluded }]);
    }
    toast.success(`✅ ${ingItem.name} added`);
  };

  const removeItem = (id) => setCart(cart.filter(c => c._id !== id));

  const total = cart.reduce((s, i) => s + i.price * i.qty, 0) + 40;

  const handlePlaceOrder = async () => {
    if (!address.trim()) return toast.error('Enter delivery address');
    setPlacing(true);
    try {
      const res = await api.post('/features/home-chefs/order', {
        restaurantId: selectedChef._id,
        items: cart.map(i => ({ menuItemId: i._id, qty: i.qty, excludedIngredients: i.excludedIngredients || [] })),
        address,
      });
      setCart([]); setCheckoutModal(false); setSelectedChef(null);
      toast.success('👩‍🍳 Home Chef order placed!');
      navigate(`/track/${res.data._id}`);
    } catch (e) {
      toast.error(e.response?.data?.message || 'Failed to place order');
    } finally { setPlacing(false); }
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center bg-gray-900">
      <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-orange-500"></div>
    </div>
  );

  if (selectedChef) {
    const available = selectedChef.homeChefMenu?.filter(i => i.remaining > 0) || [];
    return (
      <div className="min-h-screen bg-gray-900 pb-32">
        <div className="bg-[#2a1a1a] p-8 pb-10 flex flex-col items-center">
          <div className="text-6xl mb-3">{selectedChef.emoji}</div>
          <h1 className="text-2xl font-extrabold text-white">{selectedChef.name}</h1>
          <p className="text-sm text-gray-400 mt-2 text-center max-w-sm">{selectedChef.chefBio || 'Homemade food with love ❤️'}</p>
          <div className="flex gap-4 mt-3">
            <span className="text-sm text-orange-500 font-bold">⭐ {selectedChef.rating}</span>
            <span className="text-sm text-[#e67e22] font-bold">👩‍🍳 Home Chef</span>
          </div>
          <button 
            onClick={() => { setSelectedChef(null); setCart([]); }}
            className="mt-4 px-4 py-2 text-orange-500 font-bold text-sm bg-orange-500/10 rounded-full hover:bg-orange-500/20 transition"
          >
            ← Back to Chefs
          </button>
        </div>

        <div className="max-w-3xl mx-auto px-4 mt-6">
          <h2 className="text-lg font-bold text-white mb-4 px-2">Today's Menu</h2>
          {available.length === 0 ? (
            <p className="text-gray-400 text-center my-10 bg-gray-800 p-8 rounded-2xl border border-gray-700">No items available today 😔</p>
          ) : (
            <div className="space-y-4">
              {available.map(item => (
                <div key={item._id} className="bg-gray-800 rounded-2xl p-4 flex items-center border border-gray-700 shadow-md">
                  <div className="text-4xl mr-4">{item.emoji}</div>
                  <div className="flex-1">
                    <h3 className="text-base font-bold text-white">{item.name}</h3>
                    {item.description && <p className="text-xs text-gray-400 mt-1">{item.description}</p>}
                    <p className="text-sm text-orange-500 font-bold mt-2">₹{item.price} · <span className="text-xs text-gray-400 font-normal">{item.remaining} portions left</span></p>
                    {item.ingredients?.length > 0 && <span className="text-[10px] bg-green-500/20 text-green-500 font-bold px-2 py-0.5 rounded uppercase mt-2 inline-block">🥗 Customisable</span>}
                  </div>
                  <button 
                    onClick={() => handleAdd(item)}
                    className="w-10 h-10 bg-orange-500 hover:bg-orange-600 rounded-full flex items-center justify-center text-white text-2xl font-bold shadow-lg transition transform hover:scale-110 active:scale-95"
                  >
                    +
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {cart.length > 0 && (
          <div className="fixed bottom-0 left-0 right-0 bg-orange-500 p-4 sm:p-5 flex justify-between items-center shadow-[0_-10px_20px_rgba(0,0,0,0.3)] z-40">
            <span className="text-white font-bold text-base sm:text-lg">{cart.reduce((s,i)=>s+i.qty,0)} items · ₹{total}</span>
            <button 
              onClick={() => setCheckoutModal(true)}
              className="bg-white text-orange-500 font-extrabold px-5 py-2.5 rounded-xl shadow transition hover:bg-gray-50"
            >
              Checkout →
            </button>
          </div>
        )}

        <IngredientCustomModal visible={ingModal} item={ingItem} onClose={() => setIngModal(false)} onConfirm={handleIngConfirm} />

        {checkoutModal && (
          <div className="fixed inset-0 bg-black/80 flex items-end sm:items-center justify-center z-50 p-0 sm:p-4 transition-all pb-0">
            <div className="bg-gray-800 w-full sm:max-w-md p-6 sm:rounded-2xl rounded-t-3xl border border-gray-700 shadow-2xl animate-slide-up sm:animate-none">
              <h3 className="text-xl font-extrabold text-white text-center mb-6">👩‍🍳 Checkout</h3>

              <div className="bg-gray-900 rounded-xl p-4 mb-4 border border-gray-700 max-h-60 overflow-y-auto">
                {cart.map(i => (
                  <div key={i._id} className="flex justify-between items-start mb-3 pb-3 border-b border-gray-800 last:border-0 last:pb-0 last:mb-0">
                    <div className="flex-1 pr-3">
                      <span className="text-sm text-white font-medium">{i.name} <span className="text-orange-500">×{i.qty}</span></span>
                      {i.excludedIngredients?.length > 0 && <p className="text-xs text-red-500 mt-1">❌ No {i.excludedIngredients.join(', ')}</p>}
                    </div>
                    <div className="flex flex-col items-end shrink-0 pl-2">
                      <span className="text-sm text-orange-500 font-bold mb-1">₹{i.price * i.qty}</span>
                      <button onClick={() => removeItem(i._id)} className="text-xs text-red-500 hover:text-red-400 font-medium">Remove</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="bg-orange-500/10 border border-orange-500/20 p-4 rounded-xl mb-4">
                <span className="text-lg font-bold text-white flex justify-between">Total: <span className="text-orange-500">₹{total}</span></span>
                <span className="text-xs text-gray-400 text-right block mt-1">(incl. ₹40 delivery)</span>
              </div>

              <textarea 
                className="w-full bg-gray-900 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 min-h-[80px] focus:outline-none focus:border-orange-500 transition mb-6 resize-none"
                placeholder="Delivery address" 
                value={address} 
                onChange={(e) => setAddress(e.target.value)} 
              />

              <div className="flex gap-3">
                <button 
                  onClick={() => setCheckoutModal(false)} 
                  className="flex-1 py-4 rounded-xl border border-gray-600 text-gray-400 font-bold hover:bg-gray-700 transition"
                >
                  Cancel
                </button>
                <button 
                  onClick={handlePlaceOrder} 
                  disabled={placing}
                  className="flex-[2] py-4 rounded-xl bg-orange-500 hover:bg-orange-600 text-white font-bold transition shadow-lg flex justify-center items-center"
                >
                  {placing ? <div className="animate-spin rounded-full h-5 w-5 border-t-2 border-white"></div> : 'Place Order'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="bg-[#2a1a1a] p-8 pt-10 pb-12 flex flex-col items-center border-b border-gray-800">
        <div className="text-6xl mb-4">👩‍🍳</div>
        <h1 className="text-2xl font-extrabold text-[#e67e22] text-center mb-2">Home Chef Marketplace</h1>
        <p className="text-sm text-gray-400 text-center max-w-sm leading-relaxed">
          Authentic homemade food from certified local kitchens — the Etsy of food!
        </p>
      </div>

      {chefs.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 mt-12">
          <div className="text-7xl mb-4">🏠</div>
          <h2 className="text-xl font-bold text-white mb-2">No Home Chefs available</h2>
          <p className="text-sm text-gray-400 text-center max-w-xs">
            Check back soon — local chefs post their daily specials in the morning!
          </p>
        </div>
      ) : (
        <div className="max-w-2xl mx-auto p-4 py-8 space-y-4">
          {chefs.map(item => (
            <button 
              key={item._id} 
              onClick={() => setSelectedChef(item)}
              className="w-full bg-gray-800 hover:bg-gray-750 transition border border-gray-700 hover:border-gray-600 rounded-2xl p-5 flex items-center shadow-lg text-left"
            >
              <span className="text-5xl mr-4 shrink-0">{item.emoji}</span>
              <div className="flex-1 pr-2">
                <h3 className="text-lg font-bold text-white">{item.name}</h3>
                <p className="text-xs text-gray-400 mt-1 line-clamp-2 leading-relaxed">{item.chefBio || 'Homemade food with love ❤️'}</p>
                <div className="flex gap-3 mt-3">
                  <span className="text-xs font-bold text-orange-500 bg-orange-500/10 px-2 py-0.5 rounded-md">⭐ {item.rating}</span>
                  <span className="text-xs font-bold text-green-500 bg-green-500/10 px-2 py-0.5 rounded-md">
                    {item.homeChefMenu?.filter(i => i.remaining > 0).length || 0} items today
                  </span>
                </div>
              </div>
              <span className="text-gray-500 text-2xl px-2">›</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
